// ===== SỬA CÁC DÒNG NÀY RỒI LƯU (không dán token vào chat hay Git) =====
const CONFIG = {
  API: 'https://DAN_TEN_MIEN_NETLIFY.netlify.app/api/v1', // địa chỉ API của FoodSave (KHÔNG phải localhost khi dùng n8n Cloud)
  SECRET: 'DAN_N8N_SECRET_VAO_DAY',                        // trùng N8N_SECRET trong .env / biến môi trường Netlify
  DEFAULT_PAGE_ID: 'DAN_MA_FANPAGE_MAC_DINH',              // dùng khi cửa hàng chưa nhập mã Fanpage
  // Mỗi Fanpage một token. Khóa là mã Fanpage.
  PAGE_TOKENS: {
    'DAN_MA_FANPAGE_CUA_HANG': 'DAN_TOKEN_VAO_DAY'
  },
  OVERLAY: true // false = không chèn chữ lên ảnh AI
};
// =======================================================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};
if (CONFIG.SECRET && headers['x-n8n-secret'] !== CONFIG.SECRET) throw new Error('Sai mật khẩu x-n8n-secret');

const money = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'đ';
const store = body.store || {};
const product = body.product || {};
const content = body.content || {};
const label = product.label || 'yellow';
const reminder = body.variant === 'reminder';
const pageId = store.facebook_page_id || CONFIG.DEFAULT_PAGE_ID;
const useAi = Boolean(body.ai && body.ai.enabled) && !reminder && (label === 'red' || label === 'yellow');

const price = money(product.price_vnd);
const original = Number(product.original_price_vnd) > Number(product.price_vnd) ? money(product.original_price_vnd) : '';
const time = String(product.deadline_text || '').split(' ')[0];
const groupText = { cooked: 'đồ nấu chín / bánh tươi (nhấn mạnh giờ lấy trong hôm nay)', fresh: 'rau củ, thịt cá, sữa tươi (nhấn mạnh hạn dùng theo ngày)', packaged: 'đồ đóng gói (nhấn mạnh mức giảm và hạn dùng còn đủ)' }[product.food_group] || 'thực phẩm';
const tone = label === 'red' ? 'KHẨN, giải cứu gấp: sắp hết hạn, kêu gọi đến mua ngay' : 'nhẹ nhàng, thân thiện: hôm nay giá mềm, không dùng chữ "giải cứu gấp"';
const linkOk = /^https:/.test(product.url || '');

const facts = [
  `Tên cửa hàng: ${store.name}`,
  `Địa chỉ ngắn: ${store.address || ''}`,
  `Món: ${product.name}`,
  `Nhóm hàng: ${groupText}`,
  `Giá mới: ${price}`,
  original ? `Giá cũ: ${original}` : '',
  `Mức giảm: ${product.discount_percent}%`,
  `Lấy trước: ${product.deadline_text}`,
  linkOk ? `Link đặt hàng: ${product.url}` : ''
].filter(Boolean).join('\n');

const captionPrompt = [
  'Bạn viết bài đăng Facebook tiếng Việt cho một cửa hàng đang bán giải cứu thực phẩm gần hết hạn trên ứng dụng FoodSave.',
  'DỮ KIỆN CỐ ĐỊNH (giữ nguyên từng con số, KHÔNG được sửa, thêm hoặc bịa số liệu):',
  facts,
  `Giọng điệu: ${tone}.`,
  'Quy tắc: thân thiện, emoji vừa phải, 5–7 dòng, tiêu đề và giờ lấy nằm ở 2–3 dòng đầu, hashtag 3–5 cái (có #FoodSave).',
  'TUYỆT ĐỐI KHÔNG nhắc số lượng tồn kho (không viết "còn N phần"). KHÔNG ghi "ảnh minh hoạ". Nêu rõ khách tự đến cửa hàng nhận.',
  linkOk ? 'Gắn đúng link đặt hàng ở trên, chỉ một link.' : 'Không gắn link.',
  'Chỉ trả về nội dung bài đăng, không giải thích.'
].join('\n');

const brand = store.brand_color ? `Tông màu thương hiệu cửa hàng: ${store.brand_color}.` : (label === 'red' ? 'Tông ấm đỏ cam, cảm giác khẩn trương.' : 'Tông vàng ấm, tươi sáng.');
const imagePrompt = [
  `Tạo ảnh nền quảng cáo kiểu poster đồ ăn cho món "${product.name}" (${groupText}).`,
  'Món ăn nổi bật, nhìn ngon, ánh sáng đẹp, nền sạch.',
  brand,
  'Chừa trống khoảng 25% phía dưới và góc trên bên trái để chèn chữ sau.',
  'TUYỆT ĐỐI KHÔNG vẽ chữ, chữ số, logo, hình mờ hay watermark trong ảnh. Nếu có ảnh gốc đi kèm, giữ nhận diện món như ảnh gốc.'
].join('\n');

return [{
  json: {
    mode: 'store',
    useAi,
    overlayEnabled: CONFIG.OVERLAY,
    label,
    pageId,
    pageToken: CONFIG.PAGE_TOKENS[pageId] || '',
    postLogId: body.post_log_id || null,
    callbackUrl: CONFIG.API + '/marketing/callback',
    secret: CONFIG.SECRET,
    imageUrl: reminder ? '' : (product.image_url || ''),
    fallbackCaption: content.facebook,
    captionPrompt,
    imagePrompt,
    mustContain: [price, time].filter(Boolean),
    link: linkOk ? product.url : '',
    overlay: {
      title: store.name,
      badge: `GIẢM ${product.discount_percent}%`,
      line1: price,
      line2: `Lấy trước ${product.deadline_text}`
    }
  }
}];

// Dựng yêu cầu gửi Gemini (caption + ảnh) và mã hóa ảnh gốc
const ctx = $('Chuẩn bị').first().json;
const item = $input.first();
let origB64 = '';
let mime = 'image/jpeg';
if (item.binary && item.binary.orig) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'orig');
  origB64 = buf.toString('base64');
  mime = item.binary.orig.mimeType || mime;
}
const captionRequest = {
  contents: [{ parts: [{ text: ctx.captionPrompt }] }],
  generationConfig: { temperature: 0.6, maxOutputTokens: 600 }
};
const imageParts = [{ text: ctx.imagePrompt }];
if (origB64) imageParts.unshift({ inline_data: { mime_type: mime, data: origB64 } });
const imageRequest = {
  contents: [{ parts: imageParts }],
  generationConfig: { responseModalities: ['IMAGE', 'TEXT'] }
};
return [{ json: { ...ctx, origB64, origMime: mime, captionRequest, imageRequest } }];

// Tầng 1 (AI): kiểm tra kết quả Gemini. Không đạt thì dùng caption mẫu (tầng 2). Ảnh AI chỉ dùng khi caption AI đạt.
const ctx = $('Dựng yêu cầu AI').first().json;
const capRes = $('Gemini · viết caption').first().json || {};
const imgRes = $('Gemini · tạo ảnh nền').first().json || {};

let caption = '';
let tier = 'template';
try {
  const text = capRes.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
  const stockMention = /còn\s+\d+\s*(phần|suất|sản phẩm|món|cái|hộp)/i.test(text);
  const fakeTag = /minh\s*h[oọ]a/i.test(text);
  const hasNumbers = (ctx.mustContain || []).every((x) => text.includes(x));
  if (text.length > 30 && hasNumbers && !stockMention && !fakeTag) {
    caption = text;
    tier = 'ai';
  }
} catch (e) { /* dùng caption mẫu */ }
if (!caption) caption = ctx.fallbackCaption;
if (tier === 'ai' && ctx.link && !caption.includes(ctx.link)) caption += `\n👉 ${ctx.link}`;

let imgB64 = ctx.origB64 || '';
let mime = ctx.origMime || 'image/jpeg';
let aiImage = false;
if (tier === 'ai') {
  try {
    const parts = imgRes.candidates[0].content.parts;
    const part = parts.find((p) => p.inlineData || p.inline_data);
    const data = part && (part.inlineData || part.inline_data);
    if (data && data.data) { imgB64 = data.data; mime = data.mimeType || data.mime_type || 'image/png'; aiImage = true; }
  } catch (e) { /* giữ ảnh gốc */ }
}

const out = { json: { ...ctx, caption, tier, aiImage, imgB64, imgMime: mime } };
delete out.json.origB64; delete out.json.captionRequest; delete out.json.imageRequest;
if (imgB64) {
  out.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(imgB64, 'base64'), aiImage ? 'poster.png' : 'goc.jpg', mime) };
}
return [out];

// Tầng 2 (mẫu): dùng caption mẫu của FoodSave + ảnh gốc, không gọi AI
const ctx = $('Dựng yêu cầu AI').first().json;
const out = { json: { ...ctx, caption: ctx.fallbackCaption, tier: 'template', aiImage: false, imgB64: ctx.origB64 || '', imgMime: ctx.origMime || 'image/jpeg' } };
delete out.json.origB64; delete out.json.captionRequest; delete out.json.imageRequest;
if (ctx.origB64) {
  out.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(ctx.origB64, 'base64'), 'goc.jpg', ctx.origMime || 'image/jpeg') };
}
return [out];

// Chốt ảnh cuối cùng. Nếu bước chèn chữ lỗi (mất ảnh) thì dùng lại ảnh trước khi chèn chữ.
const src = $('Gộp kết quả AI').isExecuted ? $('Gộp kết quả AI').first().json : $('Dùng caption mẫu').first().json;
const item = $input.first();
const json = { ...src };
const b64 = json.imgB64;
delete json.imgB64;
let bin = item.binary && item.binary.data ? item.binary.data : null;
if (!bin && b64) {
  bin = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'poster.png', json.imgMime || 'image/png');
}
json.hasImage = Boolean(bin);
const out = { json };
if (bin) out.binary = { data: bin };
return [out];

// Gom kết quả đăng Facebook để báo về FoodSave
const c = $('Chốt ảnh').first().json;
const photo = $('Đăng ảnh lên Fanpage').isExecuted ? $('Đăng ảnh lên Fanpage').first().json : null;
const text = $('Đăng chữ lên Fanpage').isExecuted ? $('Đăng chữ lên Fanpage').first().json : null;
const res = text && text.id ? text : (photo && photo.id ? photo : null);
const ok = Boolean(res);
const pick = (r) => (r && r.error ? (r.error.message || JSON.stringify(r.error)) : '');
const error = ok ? '' : String(pick(text) || pick(photo) || 'Facebook từ chối bài đăng').slice(0, 400);
const id = ok ? String(res.post_id || res.id) : '';
return [{
  json: {
    post_log_id: c.postLogId,
    callbackUrl: c.callbackUrl,
    status: ok ? 'posted' : 'failed',
    tier: c.tier,
    external_id: id,
    external_url: ok ? 'https://www.facebook.com/' + id : '',
    error
  }
}];
